import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import './App.css';

function App() {
  return (
    <Router>
      <div className="App">
        {/* These stay on every page automatically */}
        <Navbar /> 
        
        <Routes>
          {/* This renders your Home.js component when at the base URL */}
          <Route path="/" element={<Home />} />
          
          {/* When you make aboutus.js or services.js, you just add them here:
          <Route path="/about" element={<AboutUs />} /> 
          */}
        </Routes>

        <Footer />
      </div>
    </Router>
  );
}

export default App;
